<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Support Contact Form</title>
  <style>
    :root {
      --color-bg: #1a1a1a;
      --color-surface: #2d2d2d;
      --color-text: #e0e0e0;
      --color-text-muted: #a0a0a0;
      --color-border: #404040;
      --color-focus: #4fa3ff;
      --color-error: #ff6b6b;
      --color-error-bg: #3d1f1f;
      --color-success: #51cf66;
    }

    * {
      box-sizing: border-box;
    }

    body {
      background-color: var(--color-bg);
      color: var(--color-text);
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
      font-size: 16px;
      line-height: 1.5;
      margin: 0;
      padding: 1rem;
    }

    main {
      max-width: 600px;
      margin: 0 auto;
    }

    h1 {
      font-size: 2rem;
      margin-top: 0;
      margin-bottom: 1.5rem;
      font-weight: 600;
    }

    form {
      display: flex;
      flex-direction: column;
      gap: 1.5rem;
    }

    .form-field {
      display: flex;
      flex-direction: column;
      gap: 0.5rem;
    }

    label {
      font-weight: 500;
      color: var(--color-text);
    }

    label .required {
      color: var(--color-error);
      aria-hidden: "true";
    }

    input {
      background-color: var(--color-surface);
      border: 2px solid var(--color-border);
      color: var(--color-text);
      font-size: 1rem;
      padding: 0.75rem;
      border-radius: 4px;
      font-family: inherit;
      transition: border-color 0.2s;
    }

    input:focus {
      outline: 2px solid transparent;
      border-color: var(--color-focus);
      box-shadow: 0 0 0 3px rgba(79, 163, 255, 0.2);
    }

    input::placeholder {
      color: var(--color-text-muted);
    }

    input:invalid:not(:placeholder-shown) {
      border-color: var(--color-error);
    }

    .help-text {
      font-size: 0.875rem;
      color: var(--color-text-muted);
      margin: 0;
    }

    .error-message {
      font-size: 0.875rem;
      color: var(--color-error);
      background-color: var(--color-error-bg);
      padding: 0.5rem 0.75rem;
      border-radius: 4px;
      margin: 0;
      display: none;
    }

    .error-message.visible {
      display: block;
    }

    button {
      background-color: var(--color-focus);
      color: #000;
      border: none;
      padding: 0.875rem 1.5rem;
      font-size: 1rem;
      font-weight: 600;
      border-radius: 4px;
      cursor: pointer;
      transition: background-color 0.2s;
      margin-top: 0.5rem;
    }

    button:hover:not(:disabled) {
      background-color: #3d94e8;
    }

    button:focus {
      outline: 2px solid var(--color-focus);
      outline-offset: 2px;
    }

    button:active:not(:disabled) {
      background-color: #2885d9;
    }

    button:disabled {
      opacity: 0.5;
      cursor: not-allowed;
    }

    .success-message {
      display: none;
      background-color: #2d3d2d;
      border: 2px solid var(--color-success);
      color: var(--color-success);
      padding: 1rem;
      border-radius: 4px;
      margin-bottom: 1.5rem;
    }

    .success-message.visible {
      display: block;
    }

    @media (forced-colors: active) {
      input:focus {
        outline: 3px solid;
      }

      button:focus {
        outline: 3px solid;
      }
    }

    @media (max-width: 480px) {
      h1 {
        font-size: 1.5rem;
      }

      input {
        padding: 0.875rem;
      }

      button {
        padding: 1rem;
        font-size: 1.125rem;
      }
    }
  </style>
</head>
<body>
  <main>
    <h1>Contact Support</h1>

    <div class="success-message" id="successMessage" role="status" aria-live="polite">
      Thank you! Your message has been sent successfully.
    </div>

    <form id="contactForm" novalidate>
      <div class="form-field">
        <label for="fullName">
          Full Name <span class="required" aria-hidden="true">*</span>
        </label>
        <input
          id="fullName"
          name="fullName"
          type="text"
          required
          autocomplete="name"
          aria-required="true"
          aria-invalid="false"
          aria-describedby="fullName-error"
        >
        <p id="fullName-error" class="error-message"></p>
      </div>

      <div class="form-field">
        <label for="email">
          Email Address <span class="required" aria-hidden="true">*</span>
        </label>
        <input
          id="email"
          name="email"
          type="email"
          required
          autocomplete="email"
          aria-required="true"
          aria-invalid="false"
          aria-describedby="email-error"
        >
        <p id="email-error" class="error-message"></p>
      </div>

      <div class="form-field">
        <label for="phone">Phone Number</label>
        <input
          id="phone"
          name="phone"
          type="tel"
          autocomplete="tel"
          aria-invalid="false"
          aria-describedby="phone-help phone-error"
        >
        <p id="phone-help" class="help-text">Format: (123) 456-7890 or 123-456-7890</p>
        <p id="phone-error" class="error-message"></p>
      </div>

      <button type="submit">Send Message</button>
    </form>
  </main>

  <script>
    const form = document.getElementById('contactForm');
    const fullNameInput = document.getElementById('fullName');
    const emailInput = document.getElementById('email');
    const phoneInput = document.getElementById('phone');
    const successMessage = document.getElementById('successMessage');

    const errorMessages = {
      fullName: document.getElementById('fullName-error'),
      email: document.getElementById('email-error'),
      phone: document.getElementById('phone-error')
    };

    function validateFullName(value) {
      if (!value.trim()) {
        return 'Error: Full name is required.';
      }
      if (value.trim().length < 2) {
        return 'Error: Full name must be at least 2 characters.';
      }
      return '';
    }

    function validateEmail(value) {
      if (!value.trim()) {
        return 'Error: Email address is required.';
      }
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(value)) {
        return 'Error: Enter a valid email like name@example.com.';
      }
      return '';
    }

    function validatePhone(value) {
      if (!value.trim()) {
        return '';
      }
      const phoneRegex = /^(\(\d{3}\)\s?\d{3}-\d{4}|\d{3}-\d{3}-\d{4}|\d{10})$/;
      if (!phoneRegex.test(value.replace(/\s/g, ''))) {
        return 'Error: Enter a valid phone number like (123) 456-7890 or 123-456-7890.';
      }
      return '';
    }

    function setFieldError(field, errorElement, message) {
      if (message) {
        field.setAttribute('aria-invalid', 'true');
        errorElement.textContent = message;
        errorElement.classList.add('visible');
      } else {
        field.setAttribute('aria-invalid', 'false');
        errorElement.textContent = '';
        errorElement.classList.remove('visible');
      }
    }

    function validateForm() {
      let isValid = true;
      let firstInvalidField = null;

      const fullNameError = validateFullName(fullNameInput.value);
      setFieldError(fullNameInput, errorMessages.fullName, fullNameError);
      if (fullNameError && !firstInvalidField) firstInvalidField = fullNameInput;

      const emailError = validateEmail(emailInput.value);
      setFieldError(emailInput, errorMessages.email, emailError);
      if (emailError && !firstInvalidField) firstInvalidField = emailInput;

      const phoneError = validatePhone(phoneInput.value);
      setFieldError(phoneInput, errorMessages.phone, phoneError);
      if (phoneError && !firstInvalidField) firstInvalidField = phoneInput;

      if (fullNameError || emailError || phoneError) {
        isValid = false;
      }

      if (firstInvalidField && !isValid) {
        firstInvalidField.focus();
      }

      return isValid;
    }

    fullNameInput.addEventListener('blur', () => {
      const error = validateFullName(fullNameInput.value);
      setFieldError(fullNameInput, errorMessages.fullName, error);
    });

    emailInput.addEventListener('blur', () => {
      const error = validateEmail(emailInput.value);
      setFieldError(emailInput, errorMessages.email, error);
    });

    phoneInput.addEventListener('blur', () => {
      const error = validatePhone(phoneInput.value);
      setFieldError(phoneInput, errorMessages.phone, error);
    });

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      successMessage.classList.remove('visible');

      if (validateForm()) {
        const formData = {
          fullName: fullNameInput.value,
          email: emailInput.value,
          phone: phoneInput.value || '(not provided)'
        };

        console.log('Form submitted with data:', formData);

        form.reset();
        successMessage.classList.add('visible');
        successMessage.focus();

        setTimeout(() => {
          successMessage.classList.remove('visible');
        }, 5000);
      }
    });
  </script>
</body>
</html>
