const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const cwd = process.cwd();
  const htmlPath = path.join(cwd, 'index.html');
  const htmlContent = fs.readFileSync(htmlPath, 'utf8');

  const browser = await chromium.launch();
  const page = await browser.newPage();

  await page.setContent(htmlContent, { waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });

  const results = await page.evaluate(async () => {
    return await window.axe.run({
      rules: {
        region: { enabled: true },
        'page-has-heading-one': { enabled: true },
        'color-contrast': { enabled: true },
        'label': { enabled: true },
        'form-field-multiple-labels': { enabled: true },
        'button-name': { enabled: true },
        'aria-required-attr': { enabled: true }
      }
    });
  });

  await browser.close();

  const violations = results.violations || [];
  const passes = results.passes || [];

  console.log('\n=== ACCESSIBILITY TEST RESULTS ===\n');

  if (violations.length > 0) {
    console.log(`❌ VIOLATIONS FOUND: ${violations.length}\n`);
    violations.forEach(v => {
      console.log(`Issue: ${v.id} (${v.impact})`);
      console.log(`Description: ${v.description}`);
      console.log(`Help: ${v.help}`);
      console.log(`Targets: ${v.nodes.map(n => n.target).join(', ')}`);
      console.log('---');
    });
  } else {
    console.log('✅ NO WCAG VIOLATIONS FOUND');
  }

  console.log(`\n✅ PASSES: ${passes.length} checks passed`);
  console.log('\nKey checks:');
  passes.slice(0, 10).forEach(p => {
    console.log(`  ✓ ${p.id}`);
  });

  process.exit(violations.length > 0 ? 1 : 0);
})();
