const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const cwd = process.cwd();
  const htmlPath = path.join(cwd, 'index.html');
  const htmlContent = fs.readFileSync(htmlPath, 'utf8');

  const browser = await chromium.launch();
  const page = await browser.newPage();

  await page.setContent(htmlContent, { waitUntil: 'load' });

  console.log('\n=== DETAILED ACCESSIBILITY AUDIT ===\n');

  const checks = [];

  // Check 1: Page has title
  const title = await page.title();
  checks.push({
    name: 'Page has descriptive title',
    pass: title && title.length > 0,
    detail: `Title: "${title}"`
  });

  // Check 2: Page has h1
  const h1s = await page.locator('h1').count();
  checks.push({
    name: 'Page has h1 heading',
    pass: h1s === 1,
    detail: `Found ${h1s} h1 elements`
  });

  // Check 3: Main landmark
  const main = await page.locator('main').count();
  checks.push({
    name: 'Page has main landmark',
    pass: main === 1,
    detail: `Found ${main} main elements`
  });

  // Check 4: Form has novalidate
  const form = await page.locator('form').first();
  const novalidate = await form.getAttribute('novalidate');
  checks.push({
    name: 'Form uses novalidate for custom validation',
    pass: novalidate !== null,
    detail: 'novalidate attribute present for custom error handling'
  });

  // Check 5: All required fields marked
  const requiredFields = await page.locator('input[required]').count();
  checks.push({
    name: 'Required fields have required attribute',
    pass: requiredFields === 2,
    detail: `Found ${requiredFields} required fields (expected 2)`
  });

  // Check 6: All inputs have labels
  const fullNameLabel = await page.locator('label[for="fullName"]').count();
  const emailLabel = await page.locator('label[for="email"]').count();
  const phoneLabel = await page.locator('label[for="phone"]').count();
  const allLabeled = fullNameLabel === 1 && emailLabel === 1 && phoneLabel === 1;
  checks.push({
    name: 'All inputs have associated labels',
    pass: allLabeled,
    detail: `fullName: ${fullNameLabel}, email: ${emailLabel}, phone: ${phoneLabel}`
  });

  // Check 7: Phone has helper text
  const phoneHelper = await page.locator('#phone-help').count();
  checks.push({
    name: 'Phone field has helper text with format',
    pass: phoneHelper === 1,
    detail: 'Helper text element exists'
  });

  // Check 8: Error messages have aria-describedby
  const fullNameError = await page.locator('#fullName').getAttribute('aria-describedby');
  checks.push({
    name: 'Full name has error message association',
    pass: fullNameError && fullNameError.includes('fullName-error'),
    detail: `aria-describedby: "${fullNameError}"`
  });

  // Check 9: Inputs have autocomplete
  const fullNameAuto = await page.locator('#fullName').getAttribute('autocomplete');
  const emailAuto = await page.locator('#email').getAttribute('autocomplete');
  const phoneAuto = await page.locator('#phone').getAttribute('autocomplete');
  checks.push({
    name: 'Personal data fields have autocomplete',
    pass: fullNameAuto === 'name' && emailAuto === 'email' && phoneAuto === 'tel',
    detail: `name: "${fullNameAuto}", email: "${emailAuto}", tel: "${phoneAuto}"`
  });

  // Check 10: Form fields wrapped in divs with class
  const formFields = await page.locator('.form-field').count();
  checks.push({
    name: 'Form fields wrapped in .form-field divs',
    pass: formFields === 3,
    detail: `Found ${formFields} .form-field divs (expected 3)`
  });

  // Check 11: Submit button has text
  const submitText = await page.locator('button[type="submit"]').textContent();
  checks.push({
    name: 'Submit button has descriptive text',
    pass: submitText && submitText.trim().length > 0,
    detail: `Button text: "${submitText?.trim()}"`
  });

  // Check 12: Success message has aria-live
  const successLive = await page.locator('#successMessage').getAttribute('aria-live');
  checks.push({
    name: 'Success message has aria-live for status announcements',
    pass: successLive === 'polite',
    detail: `aria-live="${successLive}"`
  });

  // Check 13: Input types are semantic
  const emailType = await page.locator('#email').getAttribute('type');
  const phoneType = await page.locator('#phone').getAttribute('type');
  checks.push({
    name: 'Inputs use semantic types (email, tel)',
    pass: emailType === 'email' && phoneType === 'tel',
    detail: `email: "${emailType}", tel: "${phoneType}"`
  });

  // Check 14: Focus visible in CSS
  const cssContent = htmlContent;
  const hasFocus = cssContent.includes(':focus') && (cssContent.includes('outline') || cssContent.includes('box-shadow'));
  checks.push({
    name: 'Focus indicators defined in CSS',
    pass: hasFocus,
    detail: 'CSS includes :focus styling'
  });

  // Check 15: Contrast in dark theme
  const hasContrast = cssContent.includes('--color-text') && cssContent.includes('--color-error') && 
                      cssContent.includes('--color-focus');
  checks.push({
    name: 'Color tokens defined for contrast management',
    pass: hasContrast,
    detail: 'CSS custom properties for colors found'
  });

  // Display results
  const passed = checks.filter(c => c.pass).length;
  const failed = checks.filter(c => !c.pass).length;

  console.log(`Results: ${passed} passed, ${failed} failed\n`);

  checks.forEach((check, i) => {
    const icon = check.pass ? '✓' : '✗';
    console.log(`${icon} ${check.name}`);
    console.log(`  ${check.detail}`);
  });

  console.log(`\n=== SUMMARY ===`);
  console.log(`${passed}/${checks.length} checks passed`);

  if (failed === 0) {
    console.log('✅ All accessibility checks passed!');
  } else {
    console.log(`❌ ${failed} issues found - review above`);
  }

  await browser.close();
  process.exit(failed > 0 ? 1 : 0);
})();
